const transitions = { draft: ["queued"], queued: ["running"], running: ["succeeded", "failed"], failed: ["queued"] };

export function moveJob(job, next) {
  if (!transitions[job.state]?.includes(next)) return { ok: false };
  job.state = next;
  return { ok: true, job };
}

